-- ==========================================================================

CREATE OR REPLACE FUNCTION public.get_dev_profile_by_discord_id(p_discord_id text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT json_build_object(
    'id', p.id,
    'user_id', p.user_id,
    'nome', p.nome,
    'nickname', p.nickname,
    'discord_id', p.discord_id,
    'discord_username', p.discord_username,
    'discord_avatar_url', p.discord_avatar_url,
    'discord_email', p.discord_email,
    'status', p.status,
    'game_id', p.game_id,
    'telefone', p.telefone,
    'custom_theme', p.custom_theme,
    'is_developer', p.is_developer,
    'is_ceo', p.is_ceo,
    'nivel', r.nivel
  )::jsonb INTO result
  FROM public.profiles p
  LEFT JOIN public.user_roles r ON r.user_id = p.user_id
  WHERE p.discord_id = p_discord_id
  LIMIT 1;

  RETURN result;
END;
$$;

CREATE OR REPLACE FUNCTION public.sync_discord_user(token text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN json_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_dev_profile_by_discord_id(text) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sync_discord_user(text) TO anon, authenticated, service_role;
