INSERT INTO public."role_permissions" ("nivel", "permissions", "updated_at", "level") VALUES ('system_patch_notes', '{"notes":[{"id":"patch-1788649959720-p88he","title":"Sistema de Notificações em Tempo Real","images":[{"id":"img-1788649950330-81nl","url":"https://adgdivossyzpwofouhrh.supabase.co/storage/v1/object/public/chat-attachments/patch-notes/1788649949158_Screenshot_1.png","name":"Screenshot_1.png","size":24697,"caption":""}],"pinned":false,"changes":["Central de notificações integrada à plataforma.","Atualização instantânea sem necessidade de recarregar a página.","Contador de notificações não lidas em tempo real.","Sincronização entre dispositivos e sessões do usuário.","Notificações para mensagens, eventos, solicitações e atualizações importantes.","Opção de marcar notificações como lidas.","Histórico de notificações.","Integração com usuários, permissões e autenticação existentes.","Sistema otimizado para desempenho e sincronização contínua."],"version":"v1.0","category":"feature","author_id":"9bb128e3-6e65-43a3-8b60-00f4dd860e0d","created_at":"2026-09-05T23:12:39.720Z","updated_at":"2026-09-05T23:13:00.846Z","author_name":"Malaca","description":"Implementado um novo sistema de notificações integrado à plataforma, com atualização 100% em tempo real e sincronizada, proporcionando maior agilidade na comunicação e acompanhamento das atividades.","is_published":true,"author_avatar":"https://cdn.discordapp.com/avatars/722320491767136346/767e1fb7dda2a0cbbb7ee881d5c85703.png?size=512"},{"id":"patch-1788631654837-mvi9h","title":"Sistema de Logs com Envio Automático para o Discord","images":[],"pinned":false,"changes":["Envio automático de logs para o Discord","Registro das principais ações realizadas na plataforma","Integração com o servidor do Discord","Identificação do usuário responsável por cada ação","Registro de data e horário das atividades","Padronização das mensagens de log","Melhoria no acompanhamento e auditoria das ações administrativas","Envio das informações de forma automática e organizada"],"version":"v1.0","category":"feature","author_id":"9bb128e3-6e65-43a3-8b60-00f4dd860e0d","created_at":"2026-09-05T18:07:34.837Z","updated_at":"2026-09-05T18:07:34.837Z","author_name":"Malaca","description":"Implementado o sistema de logs automáticos, permitindo registrar as principais ações realizadas na plataforma e enviar as informações diretamente para o servidor do Discord, facilitando o acompanhamento e a administração.","is_published":true,"author_avatar":"https://cdn.discordapp.com/avatars/722320491767136346/767e1fb7dda2a0cbbb7ee881d5c85703.png?size=512"},{"id":"patch-1788587768051-hidzs","title":"Novo Sistema de Chats em Tempo Real","images":[],"pinned":false,"changes":["Conversas individuais em tempo real","Status de envio e leitura das mensagens","Notificações e mensagens não lidas","Envio de imagens e arquivos","Suporte a emojis","Status online/offline","Busca de conversas","Interface moderna e responsiva","Histórico de mensagens"],"version":"v1.13","category":"feature","author_id":"9bb128e3-6e65-43a3-8b60-00f4dd860e0d","created_at":"2026-09-05T05:56:08.051Z","updated_at":"2026-09-05T05:56:08.051Z","author_name":"Malaca","description":"Implementado um novo sistema de chats, proporcionando uma comunicação mais rápida, moderna e intuitiva entre os usuários.","is_published":true,"author_avatar":"https://cdn.discordapp.com/avatars/722320491767136346/767e1fb7dda2a0cbbb7ee881d5c85703.png?size=512"}]}'::jsonb, '"2026-09-05T23:13:00.846Z"'::jsonb, 'system_patch_notes') ON CONFLICT DO NOTHING;
